async def act(page):
    """
    Continue from the current New Rule form state. Tasks performed:
    - Dismiss the blocking popup if present.
    - Select all Customer Groups in the "Customer Groups *" listbox so the rule
      applies to all customers.
    - Open the Actions tab/section.
    - Set the Apply combobox to a fixed-cart discount (try several likely labels).
    - Fill Discount Amount = 15.
    - Click Save (final action; must be last because it navigates away).
    """
    import asyncio

    async def _count(locator):
        try:
            return await locator.count()
        except Exception:
            return 0

    async def _click(locator, wait_ms=400):
        if await _count(locator) > 0:
            try:
                await locator.first.click()
                await page.wait_for_timeout(wait_ms)
                return True
            except Exception:
                return False
        return False

    async def _fill(locator, text):
        if await _count(locator) > 0:
            try:
                await locator.first.fill(text)
                await page.wait_for_timeout(200)
                return True
            except Exception:
                return False
        return False

    async def _select(locator, *, label=None, value=None, options=None):
        if await _count(locator) > 0:
            try:
                if options is not None:
                    await locator.first.select_option(options)
                elif label is not None:
                    await locator.first.select_option(label=label)
                elif value is not None:
                    await locator.first.select_option(value=value)
                else:
                    return False
                await page.wait_for_timeout(200)
                return True
            except Exception:
                return False
        return False

    # 0) Small pause to stabilize
    await page.wait_for_timeout(300)

    # 1) Dismiss blocking popup: try Escape, then look for a Close-like button
    try:
        await page.keyboard.press('Escape')
        await page.wait_for_timeout(250)
    except Exception:
        pass

    closed = False
    try:
        closed = await _click(page.get_by_role('button', name='Close'), wait_ms=300)
    except Exception:
        closed = False

    if not closed:
        # fallback: find any button visually indicating close/dismiss
        try:
            btns = page.get_by_role('button')
            bc = await _count(btns)
            for i in range(bc):
                b = btns.nth(i)
                try:
                    txt = (await b.inner_text() or '').strip().lower()
                except Exception:
                    txt = ''
                try:
                    title = (await b.get_attribute('title') or '').strip().lower()
                except Exception:
                    title = ''
                if any(k in txt or k in title for k in ['close', '×', 'dismiss', 'x']):
                    try:
                        await b.click()
                        await page.wait_for_timeout(300)
                        closed = True
                        break
                    except Exception:
                        continue
        except Exception:
            pass

    # 2) Select all Customer Groups via listbox "Customer Groups *"
    try:
        cg = page.get_by_role('listbox', name='Customer Groups *')
        if await _count(cg) > 0:
            labels = [
                'NOT LOGGED IN',
                'General',
                'Wholesale',
                'VIP Member',
                'Private Sales Member',
            ]
            opts = [{'label': l} for l in labels]
            # Attempt to select all by providing option label list
            await _select(cg, options=opts)
            await page.wait_for_timeout(300)
    except Exception:
        # non-fatal; continue
        await page.wait_for_timeout(200)

    # 3) Open the Actions tab/section
    try:
        opened = False
        opened = await _click(page.get_by_role('tab', name='Actions'), wait_ms=350)
        if not opened:
            opened = await _click(page.get_by_role('link', name='Actions'), wait_ms=350)
        if not opened:
            opened = await _click(page.get_by_role('button', name='Actions'), wait_ms=350)
        await page.wait_for_timeout(300)
    except Exception:
        await page.wait_for_timeout(200)

    # 4) Set Apply combobox to a fixed-cart discount; try several likely labels
    try:
        labels_to_try = [
            'Fixed amount discount for whole cart',
            'Fixed Amount Discount for whole cart',
            'Fixed amount discount',
            'Fixed Amount',
            'Fixed amount',
        ]
        applied = False
        apply_cb = page.get_by_role('combobox', name='Apply')
        if await _count(apply_cb) > 0:
            for lbl in labels_to_try:
                if await _select(apply_cb, label=lbl):
                    applied = True
                    break
        if not applied:
            # fallback: try all comboboxes
            combs = page.get_by_role('combobox')
            cc = await _count(combs)
            for i in range(cc):
                cb = combs.nth(i)
                for lbl in labels_to_try:
                    if await _select(cb, label=lbl):
                        applied = True
                        break
                if applied:
                    break
        await page.wait_for_timeout(200)
    except Exception:
        await page.wait_for_timeout(200)

    # 5) Fill Discount Amount with 15 (try common textbox names)
    try:
        await _fill(page.get_by_role('textbox', name='Discount Amount'), '15')
        await _fill(page.get_by_role('textbox', name='Discount'), '15')
    except Exception:
        pass

    # 6) Save the rule — final action (make sure this is last since it navigates away)
    try:
        saved = False
        saved = await _click(page.get_by_role('button', name='Save'), wait_ms=1200)
        if not saved:
            saved = await _click(page.get_by_role('button', name='Save Rule'), wait_ms=1200)
        if not saved:
            saved = await _click(page.get_by_role('button', name='Save and Continue Edit'), wait_ms=1200)
        if not saved:
            # last resort: click any button whose visible text contains 'save'
            btns = page.get_by_role('button')
            bc = await _count(btns)
            for i in range(bc):
                b = btns.nth(i)
                try:
                    txt = (await b.inner_text() or '').strip().lower()
                except Exception:
                    txt = ''
                if 'save' in txt:
                    try:
                        await b.click()
                        break
                    except Exception:
                        continue
    except Exception:
        await page.wait_for_timeout(300)

    # done — Save was the last action

